{
  "observation": "Using Chrome 126 on desktop, I opened Items and selected Export CSV. The CSV contained Sample-2, whose status in Items was Unavailable. I expected only Available rows. Repeating those reported actions twice produced the same row.",
  "case": {
    "title": "Export Available items",
    "steps": "1. Open Items.\n2. Apply Available.\n3. Select Export CSV.",
    "expected_result": "The CSV contains only Available rows."
  },
  "criteria": [
    "When Available is the active filter, CSV export contains only Available rows."
  ],
  "background": ""
}

{
  "questions": [
    "At the moment Export CSV was selected, what filter selection did Items show?"
  ]
}
